"""Shared result envelope and literal run_02/run_03 pixel measurements."""
import math
from pathlib import Path
import numpy as np
from PIL import Image

DIRS = ['S','SW','W','NW','N','NE','E','SE']
COUNTS = {'idle':8, 'walk':8, 'cast':12}

def result(id, subject, value=None, threshold=None, op='<=', unit='', notes='', passed=None, evidence=()):
    if passed is None and value is not None and threshold is not None:
        passed = bool({'<=':lambda:value<=threshold, '<':lambda:value<threshold,
                       '>=':lambda:value>=threshold, '==':lambda:value==threshold}[op]())
    return dict(id=id, subject=str(subject), passed=passed, value=value, threshold=threshold,
                op=op, unit=unit, evidence=list(evidence), notes=notes)

def rgba(image):
    if isinstance(image, (str, Path)):
        with Image.open(image) as im: return im.convert('RGBA')
    if isinstance(image, np.ndarray): return Image.fromarray(image.astype(np.uint8)).convert('RGBA')
    return image.convert('RGBA')

def measure(image):
    a=np.array(image.convert('RGBA')); mask=a[...,3]>=128
    ys,xs=np.where(mask)
    if not len(xs): return {'valid':False}
    box=[int(xs.min()),int(ys.min()),int(xs.max()+1),int(ys.max()+1)]
    lum=a[...,:3].astype(float)@np.array([.2126,.7152,.0722])
    n=math.ceil(len(xs)*.05)
    ix=np.argsort(lum[mask],kind='stable')[-n:]
    c=[float(xs[ix].mean()),float(ys[ix].mean())]
    center=[(box[0]+box[2]-1)/2,(box[1]+box[3]-1)/2]
    edge=(a[...,3]>0)&(a[...,3]<255)
    green_excess=a[...,1].astype(float)-np.maximum(a[...,0],a[...,2])
    border=np.concatenate([a[0,:,3],a[-1,:,3],a[:,0,3],a[:,-1,3]])
    return {'valid':True,'bbox':box,'height':box[3]-box[1],
            'transparent_fraction':float(np.mean(a[...,3]==0)),
            'border_alpha_max':int(border.max()),'light_centroid':c,'silhouette_center':center,
            'light_pass':bool(c[0]<center[0] and c[1]<center[1]),
            'brightest_5pct_pixels':n,'partial_alpha_pixels':int(edge.sum()),
            'edge_mean_rgb_value':float(a[...,:3][edge].mean()) if edge.any() else None,
            'green_contaminated_pixels':int(np.count_nonzero(edge & (green_excess>20)))}

def pixels(path):
    im=rgba(path);bg=Image.new('RGBA',im.size,(20,25,34,255));bg.alpha_composite(im)
    return np.array(bg)[...,:3].astype(float),np.array(im)[...,3]>0

def difference(a,b):
    x,m=pixels(a);y,n=pixels(b);v=np.abs(x-y);u=m|n
    return {'canvas':float(v.mean()),'foreground_union':float(v[u].mean()) if u.any() else None}


def pair_differences(frames):
    if len(frames)<2: raise ValueError('At least two frames required')
    return [difference(frames[i],frames[(i+1)%len(frames)]) for i in range(len(frames))]
"""64px binary alpha, centroid/area alignment, aligned IoU and seven Hu moments.
Hu moments are a screen, not the primary shape distance. Threshold is caller-set.
"""
import numpy as np
from scipy import ndimage
from PIL import Image
from .common import rgba, result

def descriptor(alpha):
    if isinstance(alpha,dict): return alpha
    if isinstance(alpha,np.ndarray) and alpha.ndim==2:
        a=alpha.astype(float);a=a*255 if a.max(initial=0)<=1 else a
        im=Image.fromarray(a.astype(np.uint8),'L')
    elif isinstance(alpha,Image.Image) and alpha.mode=='L': im=alpha
    else: im=rgba(alpha).getchannel('A')
    m=np.array(im.resize((64,64),Image.Resampling.LANCZOS))>=128
    y,x=np.where(m)
    if not len(x): raise ValueError('Empty silhouette')
    cx,cy=x.mean(),y.mean();x=x-cx;y=y-cy;area=len(x)
    n=lambda p,q:float(np.sum(x**p*y**q)/area**(1+(p+q)/2))
    a,b,c,d,e,f,g=n(2,0),n(0,2),n(1,1),n(3,0),n(1,2),n(2,1),n(0,3)
    hu=[a+b,(a-b)**2+4*c*c,(d-3*e)**2+(3*f-g)**2,(d+e)**2+(f+g)**2,
        (d-3*e)*(d+e)*((d+e)**2-3*(f+g)**2)+(3*f-g)*(f+g)*(3*(d+e)**2-(f+g)**2),
        (a-b)*((d+e)**2-(f+g)**2)+4*c*(d+e)*(f+g),
        (3*f-g)*(d+e)*((d+e)**2-3*(f+g)**2)-(d-3*e)*(f+g)*(3*(d+e)**2-(f+g)**2)]
    return dict(mask=m,area=area,centroid=[float(cx),float(cy)],hu=hu)

def aligned_metrics(a,b):
    a,b=descriptor(a),descriptor(b)
    # Shared padded canvas avoids clipping during area normalization.
    target_area=512.;center=np.array([63.5,63.5])
    def align(d):
        scale=(target_area/d['area'])**.5
        matrix=np.eye(2)/scale
        offset=np.array(d['centroid'][::-1])-center/scale
        return ndimage.affine_transform(d['mask'].astype(float),matrix,offset,output_shape=(128,128),order=0)>0
    x,y=align(a),align(b); union=(x|y).sum()
    iou=float((x&y).sum()/union) if union else 0.
    ex=x&~ndimage.binary_erosion(x);ey=y&~ndimage.binary_erosion(y)
    contour=float((ndimage.distance_transform_edt(~ex)[ey].mean()+ndimage.distance_transform_edt(~ey)[ex].mean())/2)
    return dict(aligned_iou=iou,contour_distance=contour,hu_a=a['hu'],hu_b=b['hu'])

def distance(a,b):
    return 1-aligned_metrics(a,b)['aligned_iou']

def evaluate(image,master,subject='',threshold=None):
    import json
    try: m=aligned_metrics(image,master)
    except ValueError as e: return result('silhouette64',subject,notes=str(e))
    return result('silhouette64',subject,1-m['aligned_iou'],threshold,unit='1-iou',notes=('UNEVALUABLE verdict: no calibrated threshold supplied; ' if threshold is None else '')+json.dumps(m))
"""Separate root registration, visible sole midpoint, and planted trajectories.
A visible two-sole midpoint is NOT an independently annotated ground/root.
Trajectory inputs require persistent reviewed foot IDs; automatic x-sorting
cannot determine anatomical identity or planted intervals.
"""
import json
import numpy as np
from .common import rgba, result
from .register import frame_contacts

def root_anchor(anchor=None, subject='', pivot=(256,400), tolerance=4):
    if anchor is None:
        return result('g2_pivot',subject,threshold=tolerance,unit='px',notes='UNEVALUABLE: independent reviewed root anchor required; sole midpoint is separate')
    a=np.asarray(anchor,float)
    if a.shape!=(2,) or not np.isfinite(a).all(): raise ValueError('Expected finite root XY')
    error=np.abs(a-pivot)
    return result('g2_pivot',subject,float(error.max()),tolerance,unit='px',notes=json.dumps({'root':a.tolist(),'error_xy':error.tolist()}))

def visible_midpoint(image, subject='', regions=None, pivot=(256,400), tolerance=4):
    try:
        points=frame_contacts(rgba(image),regions)
    except ValueError as e:
        return result('g2_sole_midpoint',subject,threshold=tolerance,unit='px',notes=str(e))
    error=np.abs(np.mean(points,axis=0)-pivot)
    return result('g2_sole_midpoint',subject,float(error.max()),tolerance,unit='px',
                  notes=json.dumps({'points':points,'error_xy':error.tolist(),'method':'reviewed regions' if regions is not None else 'automatic run_03 fallback'}))

def planted_trajectory(points=None, planted=None, subject='', tolerance=None, expected_leads=None):
    """Report planted XY trajectories and max adjacent displacement in pixels.
    points: T x F x 2, persistent reviewed IDs; planted: T x F bool.
    tolerance is optional because in-place gait legitimately moves a planted sole.
    expected_leads optionally specifies the reviewed planted foot index per frame.
    """
    if points is None or planted is None:
        return result('g2_planted_sole',subject,threshold=tolerance,unit='px/frame',notes='UNEVALUABLE: persistent foot IDs and reviewed planted intervals required')
    p=np.asarray(points,float); m=np.asarray(planted,bool)
    if p.ndim!=3 or p.shape[2]!=2 or m.shape!=p.shape[:2] or not np.isfinite(p).all():
        raise ValueError('Expected finite T x F x 2 points and T x F planted flags')
    segments=[]
    for t in range(1,len(p)):
        for f in range(p.shape[1]):
            if m[t-1,f] and m[t,f]:
                delta=p[t,f]-p[t-1,f]
                segments.append(dict(frame=t,foot=f,delta_xy=delta.tolist(),distance=float(np.linalg.norm(delta))))
    notes={'points':p.tolist(),'planted':m.tolist(),'segments':segments}
    rows=[result('g2_planted_sole',subject,max((s['distance'] for s in segments),default=None),tolerance,
                 unit='px/frame',notes=(('UNEVALUABLE verdict: trajectory reported without calibrated tolerance; ' if tolerance is None else '')+json.dumps(notes)) if segments else 'UNEVALUABLE: no consecutive planted samples; '+json.dumps(notes))]
    if expected_leads is not None:
        if len(expected_leads)!=len(p): raise ValueError('Lead schedule length mismatch')
        mismatch=sum(not m[t,f] or m[t].sum()!=1 for t,f in enumerate(expected_leads))
        rows.append(result('g2_planted_leads',subject,int(mismatch),0,unit='frames',notes='Compared to supplied reviewed lead schedule'))
    return rows

def evaluate(image, subject='', anchor=None, regions=None, points=None, planted=None, **kwargs):
    trajectory=planted_trajectory(points,planted,subject,**kwargs)
    return [root_anchor(anchor,subject),visible_midpoint(image,subject,regions)]+(trajectory if isinstance(trajectory,list) else [trajectory])
"""Literal run_03 character sheet/atlas/contact layout with explicit availability.
VFX packing is dependency-injected: run_03/package.py delegates its pixel
operations to vfx.py, which is not an authorized source for this port.
"""
import json
from pathlib import Path
import numpy as np
from PIL import Image
from .common import DIRS,COUNTS,rgba


def package(frames_dir,out_dir):
    root=Path(frames_dir);out=Path(out_dir)
    character={'status':'IN_PROGRESS','directions':DIRS,'canvas':[512,512],'pivot':[256,400],'cast_spawn_index':5,'animations':{}}
    total=0
    for anim,count in COUNTS.items():
        sheet=Image.new('RGBA',(count*512,8*512));entries=[];available={}
        for row,d in enumerate(DIRS):
            files=sorted((root/anim/d).glob('*.png'));available[d]=len(files)
            seen=set()
            for f in files:
                index=int(f.stem.split('_')[-1])
                if not 0<=index<count or index in seen:raise ValueError('Invalid or duplicate frame index')
                seen.add(index);im=rgba(f)
                if im.size!=(512,512):raise ValueError('Character frame canvas must be 512x512')
                rect=[index*512,row*512,512,512];sheet.paste(im,tuple(rect[:2]))
                entries.append(dict(direction=d,index=index,rect=rect,file='frames/'+f.relative_to(root).as_posix()))
        total+=len(entries)
        for folder,im in [('sheets',sheet),('contact',sheet.resize((sheet.width//4,sheet.height//4),Image.Resampling.LANCZOS))]:
            path=out/folder;path.mkdir(parents=True,exist_ok=True);im.save(path/f'{anim}.png')
        character['animations'][anim]={'sheet':f'sheets/{anim}.png','fps':{'idle':8,'walk':10,'cast':16}[anim],'loop':anim!='cast','count':count,'available':available,'frames':entries}
    character.update(available_frames=total,required_frames=224)
    if total==224:character['status']='FRAMES_COMPLETE_ACCEPTANCE_PENDING'
    out.mkdir(parents=True,exist_ok=True);(out/'atlas.json').write_text(json.dumps(character,indent=2)+'\n')
    return character


def composite_sockets(frames_dir):
    """Literal blue-frost selection and reviewed recovery sockets from package.py."""
    root=Path(frames_dir);sockets={}
    for d in ['S','E']:
        sockets[d]=[]
        for i in range(12):
            a=np.array(rgba(root/f'cast/{d}/cast_{d}_{i:02d}.png')).astype(float)
            mask=(a[...,2]>a[...,0]+25)&(a[...,2]>90)&(a[...,3]>64)
            mask[280:]=False;ys,xs=np.where(mask)
            sockets[d].append([float(np.median(xs)),float(np.median(ys))] if len(xs) else None)
        sockets[d][8]={'S':[201,166],'E':[277,155]}[d]
        if any(sockets[d][i] is None for i in range(2,9)):raise ValueError(f'Missing active spell socket {d}')
    return sockets


def vfx_atlas(sizes,counts,pack_module):
    """Preserve package.py metadata; supplied callback writes sheets/emissive."""
    data={'status':'FRAMES_COMPLETE_PLAYBACK_UNVERIFIED','fps':20,'modules':{}}
    for module,count in counts.items():
        pack_module(module);w,h=sizes[module]
        data['modules'][module]={'sheet':f'sheets/{module}.png','emissive':f'sheets/{module}_emissive.png','canvas':[w,h],
          'pivot':[170,64] if module=='travel' else [w//2,h//2],'fps':20,'loop':module=='travel','count':count,
          'frames':[dict(index=i,rect=[i*w,0,w,h],file=f'frames/{module}/{module}_{i:02d}.png') for i in range(count)]}
    return data
"""CLI and regression measurements. Never loads implicit annotation/config files.
Optional reviewed contacts/root/plant data can be supplied to run() as dictionaries.
"""
import argparse
import json
from pathlib import Path
import sys
import numpy as np
if __package__ in (None,''):
    sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from gates.common import DIRS, COUNTS, rgba, measure, difference, pair_differences, result
from gates.register import frame_contacts
from gates import g1_height,g2_pivot,g3_light,g5_drift,g6_seam,g9_alpha,drift48,silhouette64


def measurements(frames_dir, regions=None):
    """Regenerate legacy height/pivot/drift/seam values from actual PNGs.
    regions keys are relative animation/direction/filename paths. The regression
    lock is never used as an annotation or as a source of computed values.
    """
    root=Path(frames_dir); directions={}; regions=regions or {}
    for d in DIRS:
        animations={}
        for anim,count in COUNTS.items():
            files=sorted((root/anim/d).glob('*.png')); rows=[]
            for f in files:
                im=rgba(f);r=measure(im);r['file']=f.relative_to(root).as_posix()
                try:
                    p=frame_contacts(im,regions.get(r['file']))
                    r.update(sole_points=p,sole_midpoint_error=np.abs(np.mean(p,axis=0)-[256,400]).tolist())
                except ValueError as e: r['contact_error']=str(e)
                rows.append(r)
            item={'frames':rows,'available':len(files),'required':count}
            if anim in ('idle','walk') and len(files)==count:
                item['adjacent_and_seam']=pair_differences(files)
                cast=root/'cast'/d/f'cast_{d}_05.png'
                if cast.exists(): item['cross_cast_05']=difference(files[0],cast)
            animations[anim]=item
        directions[d]={'animations':animations}
    return {'directions':directions}


def regression_diff(actual, expected, tolerance=1e-3):
    """Every recorded height, pivot XY, pair MAD (canvas/union), cross MAD.
    Returns precise differences rather than modifying measurements to match.
    """
    diffs=[]; compared=0
    def compare(path,a,b):
        nonlocal compared
        if isinstance(b,list):
            if not isinstance(a,list) or len(a)!=len(b):
                diffs.append(dict(path=path,expected=b,actual=a));return
            for i,v in enumerate(b):compare(f'{path}/{i}',a[i],v)
        elif isinstance(b,dict):
            for k,v in b.items():compare(f'{path}/{k}',a.get(k) if isinstance(a,dict) else None,v)
        else:
            compared+=1
            if a is None or abs(a-b)>tolerance:diffs.append(dict(path=path,expected=b,actual=a,delta=None if a is None else a-b))
    for d,r in expected['directions'].items():
        for anim,item in r['animations'].items():
            got=actual['directions'][d]['animations'][anim];prefix=f'{d}/{anim}'
            compare(prefix+'/available',got['available'],item['available'])
            by_name={Path(x['file']).name:x for x in got['frames']}
            for row in item['frames']:
                name=Path(row['file']).name; other=by_name.get(name,{})
                for key in ('height','sole_points','sole_midpoint_error'):
                    if key in row:compare(f'{prefix}/{name}/{key}',other.get(key),row[key])
            for key in ('adjacent_and_seam','cross_cast_05'):
                if key in item:compare(prefix+'/'+key,got.get(key),item[key])
    return dict(tolerance=tolerance,compared=compared,differences=diffs,within_tolerance=not diffs)


def run(frames_dir,master,regions=None,anchors=None,plants=None,dark_threshold=None):
    root=Path(frames_dir); rows=[];regions=regions or {};anchors=anchors or {};plants=plants or {}
    master=rgba(master)
    for d in DIRS:
        for anim,count in COUNTS.items():
            files=sorted((root/anim/d).glob('*.png')); subject=f'{anim}/{d}'
            rows.append(result('frame_count',subject,len(files),count,op='==',unit='frames'))
            for f in files:
                key=f.relative_to(root).as_posix();im=rgba(f)
                rows.extend([g1_height.evaluate(im,master,key),g3_light.evaluate(im,key),
                             g2_pivot.root_anchor(anchors.get(key),key),g2_pivot.visible_midpoint(im,key,regions.get(key)),
                             silhouette64.evaluate(im,master,key)])
                rows.extend(g9_alpha.evaluate(im,key,dark_threshold))
            if anim in ('idle','walk'):
                if len(files)==count:
                    cast=root/'cast'/d/f'cast_{d}_05.png';cast=cast if cast.exists() else None
                    rows.extend([g5_drift.evaluate(files,cast,subject),drift48.evaluate(files,cast,subject)])
                    rows.extend(g6_seam.evaluate(files,subject))
                else:
                    for id in ('g5_drift','drift48','g6_seam','g6b'):
                        rows.append(result(id,subject,notes='UNEVALUABLE: incomplete sequence'))
                plant=g2_pivot.planted_trajectory(subject=subject,**plants.get(subject,{}))
                rows.extend(plant if isinstance(plant,list) else [plant])
    return rows


def main():
    p=argparse.ArgumentParser();p.add_argument('--frames-dir',required=True);p.add_argument('--master',required=True);p.add_argument('--out',required=True)
    a=p.parse_args();rows=run(a.frames_dir,a.master);out=Path(a.out);out.parent.mkdir(parents=True,exist_ok=True)
    out.write_text(json.dumps(rows,indent=2,allow_nan=False)+'\n')

if __name__=='__main__':main()
