"""Particle-preserving emission matting and VFX sheet packing."""
from pathlib import Path
import argparse,json
import numpy as np
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parent
SIZES={'cast':(256,256),'travel':(256,128),'impact':(384,384)}
COUNTS={'cast':8,'travel':6,'impact':10}

def emission_matte(image):
    a=np.array(image.convert('RGBA'));rgb=a[...,:3].astype(float)
    if 'A' in image.getbands() and (a[...,3]==0).mean()>.01:
        return image.convert('RGBA'),{'method':'native alpha','discarded_components':0}
    border=np.concatenate([rgb[0],rgb[-1],rgb[:,0],rgb[:,-1]])
    if np.mean(border.max(axis=1)<=3)<.98:raise ValueError('Emission plate border is not uniformly black')
    value=rgb.max(axis=2);alpha=value/255
    color=np.divide(rgb,alpha[...,None],out=np.zeros_like(rgb),where=alpha[...,None]>0)
    out=np.dstack([color,alpha*255]).round().clip(0,255).astype('uint8');out[value<=2]=0
    return Image.fromarray(out),{'method':'black emission plate; alpha=max(RGB), straight RGB=emission/alpha','noise_floor':2,'discarded_components':0}

def edge_metrics(im):
    a=np.array(im.convert('RGBA'));edge=(a[...,3]>0)&(a[...,3]<255)
    border=np.concatenate([a[0,:,3],a[-1,:,3],a[:,0,3],a[:,-1,3]])
    values=a[...,:3][edge].astype(float);lum=values@np.array([.2126,.7152,.0722]) if len(values) else np.array([])
    return {'partial_alpha_pixels':int(edge.sum()),'edge_mean_rgb':float(values.mean()) if len(values) else None,
            'edge_mean_luminance':float(lum.mean()) if len(lum) else None,'edge_luminance_p10':float(np.percentile(lum,10)) if len(lum) else None,
            'border_alpha_max':int(border.max()),'nonzero_alpha_pixels':int((a[...,3]>0).sum())}

def prepare(name,module,start,number=4):
    source=Image.open(ROOT/'source'/f'{name}.png');side=source.width//2;target=SIZES[module]
    if side<max(target):raise ValueError('Insufficient native cell resolution; would upscale')
    out=ROOT/'vfx/frames'/module;out.mkdir(parents=True,exist_ok=True);rows=[]
    for i in range(number):
        x=i%2*side;y=i//2*side;cell=source.crop((x,y,x+side,y+side))
        matte,info=emission_matte(cell)
        if module=='travel':
            # Uniform reduction followed by fixed central crop; no stretching.
            reduced=matte.resize((256,256),Image.Resampling.LANCZOS)
            pixels=np.array(reduced).astype(float)
            energy=(pixels[...,:3].mean(axis=2)*pixels[...,3]/255)**2
            center_y=float((energy*np.arange(256)[:,None]).sum()/energy.sum())
            shift=round(127.5-center_y)
            registered=Image.new('RGBA',(256,256));registered.paste(reduced,(0,shift));reduced=registered
            info.update(centerline_source_y=center_y,vertical_translation_px=shift)
            frame=reduced.crop((0,64,256,192))
        else:frame=matte.resize(target,Image.Resampling.LANCZOS)
        index=start+i;frame.save(out/f'{module}_{index:02d}.png');metrics=edge_metrics(frame);rows.append(dict(index=index,extraction=info,**metrics))
    (ROOT/'evidence'/f'{name}_metrics.json').write_text(json.dumps(rows,indent=2)+'\n');pack(module)
    print(json.dumps(rows,indent=2))

def pack(module):
    size=SIZES[module];files=sorted((ROOT/'vfx/frames'/module).glob('*.png'));sheet=Image.new('RGBA',(size[0]*len(files),size[1]))
    for i,f in enumerate(files):sheet.paste(Image.open(f),(i*size[0],0))
    folder=ROOT/'vfx/sheets';folder.mkdir(parents=True,exist_ok=True);sheet.save(folder/f'{module}.png')
    a=np.array(sheet).astype(float);emission=a[...,:3]*(a[...,3,None]/255);lum=emission@np.array([.2126,.7152,.0722]);Image.fromarray(lum.clip(0,255).astype('uint8')).save(folder/f'{module}_emissive.png')
    contact=ROOT/'vfx/contact';contact.mkdir(exist_ok=True);sheet.resize((max(1,sheet.width//4),max(1,sheet.height//4)),Image.Resampling.LANCZOS).save(contact/f'{module}.png')
    review=Image.new('RGB',(sheet.width,sheet.height*3+72));draw=ImageDraw.Draw(review)
    for j,(color,label) in enumerate([((20,25,34),'DARK'),((230,233,239),'LIGHT'),((70,80,130),'BLUE')]):
        bg=Image.new('RGBA',sheet.size,(*color,255));bg.alpha_composite(sheet);review.paste(bg,(0,j*(sheet.height+24)+24));draw.text((8,j*(sheet.height+24)+4),label,fill='white')
    review.save(ROOT/'evidence'/f'vfx_{module}_edges.png')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('name');p.add_argument('module',choices=SIZES);p.add_argument('start',type=int);p.add_argument('--number',type=int,default=4);a=p.parse_args();prepare(a.name,a.module,a.start,a.number)
"""Literal run_02 character matte; opt-in detached-particle preservation.
Native alpha retains dark interiors. Default dust filtering matches run_02.
"""
import numpy as np
from PIL import Image
from scipy import ndimage

def extract(image, preserve_particles=False):
    a = np.array(image.convert('RGBA')).astype(float)
    native = bool('A' in image.getbands() and np.mean(a[..., 3] == 0) > .01)
    if native:
        method = 'native alpha'
        out = a.astype(np.uint8)
    else:
        rgb = a[..., :3]
        border = np.concatenate([rgb[:10].reshape(-1,3),rgb[-10:].reshape(-1,3),
                                 rgb[:,:10].reshape(-1,3),rgb[:,-10:].reshape(-1,3)])
        green_fraction = float(np.mean((border[:,1] > 210) &
                                       (border[:,0] < 45) & (border[:,2] < 45)))
        if green_fraction < .95:
            raise ValueError(f'No native alpha or uniform green plate: border green fraction {green_fraction:.4f}')
        excess = rgb[...,1] - np.maximum(rgb[...,0],rgb[...,2])
        alpha = np.clip(1 - excess / 255, 0, 1)
        alpha[excess <= 12] = 1
        alpha[excess >= 250] = 0
        clean = (rgb - (1-alpha[...,None])*np.array([0,255,0])) / np.maximum(alpha[...,None],1e-6)
        out = np.dstack([np.clip(clean,0,255),alpha*255]).round().astype(np.uint8)
        method = 'green excess matte + inverse straight-alpha compositing'
    # Remove only detached alpha dust, never dark character pixels.
    labels, n = ndimage.label(out[...,3] >= 128)
    counts = np.bincount(labels.ravel())
    counts[0] = 0
    main_component = int(counts.argmax())
    support = ndimage.binary_dilation(labels == main_component, iterations=3)
    dust = int(np.count_nonzero((out[...,3]>0) & ~support))
    if not preserve_particles:
        out[~support] = 0
    else:
        dust = 0
    out[out[...,3] == 0, :3] = 0
    mask = out[...,3] >= 128
    if mask.sum() < 100:
        raise ValueError('Empty extracted subject')
    return Image.fromarray(out), {'method':method, 'removed_background_or_detached_alpha_dust_pixels':dust,
                                'native_input_alpha':native}


def remove_chroma_key(image, preserve_particles=False):
    return extract(image, preserve_particles=preserve_particles)[0]
"""Uniform reduction/translation and independently remeasured reviewed soles.
No source configuration or annotation files are loaded implicitly.
"""
import numpy as np
from PIL import Image
from scipy import ndimage

def registration(image, annotations, size=512, locked_scale=None):
    scale = locked_scale if locked_scale is not None else 240 / annotations['body_height']
    scale *= size / 512
    if scale > 1:
        raise ValueError('Would upscale source artwork')
    if image.width != image.height:
        raise ValueError('Character source must be square')
    scaled_side = round(image.width * scale)
    scale = scaled_side / image.width
    anchor = np.array(annotations['anchor'],float)
    target = np.array([256,400],float) * size / 512
    translation = target-scale*anchor
    reduced=image.resize((scaled_side,scaled_side),Image.Resampling.LANCZOS)
    inverse = (1,0,-translation[0],0,1,-translation[1])
    # Prefilter the reduction; Pillow uses associated-alpha for RGBA sampling.
    result=reduced.transform((size,size),Image.Transform.AFFINE,inverse,
                           resample=Image.Resampling.BICUBIC)
    pixels=np.array(result)
    excess=pixels[...,1].astype(float)-np.maximum(pixels[...,0],pixels[...,2])
    spill=(pixels[...,3]>0)&(pixels[...,3]<246)&(excess>12)
    pixels[spill,1]=np.maximum(pixels[spill,0],pixels[spill,2])
    pixels[pixels[...,3]==0,:3]=0
    result=Image.fromarray(pixels)
    points={name:(np.array(point)*scale+translation).tolist()
            for name,point in annotations.get('landmarks',{}).items()}
    points['registered_anchor']=(anchor*scale+translation).tolist()
    return result, {'scale':scale, 'translation':translation.tolist(),
                    'resampled_green_edge_pixels_despilled':int(spill.sum()),
                    'source_anchor':anchor.tolist(),'transformed_landmarks':points,
                    'body_height_after_transform':annotations['body_height']*scale,
                    'transform_generated_anchor_is_not_independent_validation':True}

def sole_contacts(image, regions):
    mask = np.array(image.convert('RGBA'))[..., 3] >= 128
    points = []
    if len(regions) != 2:
        raise ValueError('Exactly two reviewed sole regions are required')
    for x0, y0, x1, y1 in regions:
        if not (0 <= x0 < x1 <= image.width and 0 <= y0 < y1 <= image.height):
            raise ValueError('Sole region outside image')
        roi = mask[y0:y1, x0:x1]
        yy, xx = np.where(roi)
        if not len(yy):
            raise ValueError('Empty sole region')
        bottom = int(yy.max())
        if bottom >= roi.shape[0] - 1:
            raise ValueError('Sole region clips the contact; review the region')
        low_x = xx[yy >= bottom - 1]
        if low_x.min() == 0 or low_x.max() == roi.shape[1] - 1:
            raise ValueError('Sole region clips the contact horizontally')
        points.append([float(np.median(low_x) + x0), float(bottom + y0)])
    return points

def measured_anchor(image, regions):
    return np.mean(sole_contacts(image, regions), axis=0).tolist()

def preflight(image, regions, pivot=(256, 400), tolerance=4):
    points = sole_contacts(image, regions)
    midpoint = np.mean(points, axis=0)
    error = np.abs(midpoint - pivot)
    return {'points': points, 'midpoint': midpoint.tolist(),
            'error_xy': error.tolist(), 'pass': bool((error <= tolerance).all())}

def contacts(im, regions):
    mask = np.array(im.convert('RGBA'))[...,3] >= 128
    below = np.zeros_like(mask); below[:-1] = mask[1:]
    contour = mask & ~below
    points = []
    if len(regions) != 2: raise ValueError('Exactly two reviewed sole regions required')
    for x0,y0,x1,y1 in regions:
        if not (0 <= x0 < x1 <= im.width and 0 <= y0 < y1 <= im.height):
            raise ValueError('Sole region outside image')
        yy,xx = np.where(contour[y0:y1,x0:x1])
        if not len(yy): raise ValueError('No visible lower contour')
        bottom = yy.max(); xs = xx[yy >= bottom-1]
        if bottom == y1-y0-1 or xs.min() == 0 or xs.max() == x1-x0-1:
            raise ValueError('Review region truncates lowest sole contour')
        points.append([float(np.median(xs)+x0),float(bottom+y0)])
    return {'points':points,'midpoint':np.mean(points,axis=0).tolist()}

def front_contacts(im,exclude_thin_staff=False):
    a=np.array(im)[...,3]>=128;ys,xs=np.where(a)
    if not len(xs): raise ValueError('Empty alpha subject')
    cx=(xs.min()+xs.max())/2;floor=ys.min()+.72*(ys.max()-ys.min())
    below=np.zeros_like(a);below[:-1]=a[1:];edge=a&~below
    if exclude_thin_staff:
        # A complete lower-foot component joins heel and toe naturally. Prefer
        # these when both feet separate; overlapping side-view boots still need
        # the global lower-contour fallback below.
        lower=a.copy();lower[:int(ys.min()+.78*(ys.max()-ys.min()))]=False
        components,n=ndimage.label(lower);feet=[]
        for k in range(1,n+1):
            yy,xx=np.where(edge&(components==k))
            if len(xx) and xx.max()-xx.min()>=(ys.max()-ys.min())*.035:
                bottom=yy.max();feet.append([float(np.median(xx[yy>=bottom-1])),float(bottom)])
        feet.sort(key=lambda p:p[1],reverse=True)
        if len(feet)>=2:return sorted(feet[:2],key=lambda p:p[0])
        edge[:int(ys.min()+.78*(ys.max()-ys.min()))]=False
        labels,n=ndimage.label(ndimage.binary_dilation(edge,iterations=max(1,round(im.width/1254*2))))
        candidates=[]
        for k in range(1,n+1):
            yy,xx=np.where(edge&(labels==k))
            if len(xx) and xx.max()-xx.min()>=(ys.max()-ys.min())*.035:
                bottom=yy.max();candidates.append([float(np.median(xx[yy>=bottom-1])),float(bottom)])
        candidates.sort(key=lambda p:p[1],reverse=True)
        selected=[]
        for candidate in candidates:
